<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api } from '../../services/api'
import type { Machine, Reservation, ReservationStatus, User } from '../../types/domain'
const reservations = ref<Reservation[]>([]); const residents = ref<User[]>([]); const machines = ref<Machine[]>([]); const errorMessage = ref(''); const search = ref(''); const status = ref<'all' | ReservationStatus>('all'); const date = ref(''); const showCreate = ref(false); const userId = ref(''); const machineId = ref(''); const start = ref(''); const end = ref('')
onMounted(async () => { try { [reservations.value, residents.value, machines.value] = await Promise.all([api.reservations.list(), api.users.list(), api.machines.list()]) } catch (error) { errorMessage.value = error instanceof Error ? error.message : 'Unable to load reservations.' } })
const filtered = computed(() => reservations.value.filter((reservation) => { const query = search.value.toLowerCase(); return (!query || `${reservation.userName} ${reservation.machineName}`.toLowerCase().includes(query)) && (status.value === 'all' || reservation.status === status.value) && (!date.value || reservation.start.slice(0, 10) === date.value) }))
async function cancel(reservation: Reservation) { try { Object.assign(reservation, await api.reservations.cancel(reservation.id)) } catch (error) { errorMessage.value = error instanceof Error ? error.message : 'Unable to cancel reservation.' } }
async function createReservation() { try { const resident = residents.value.find((item) => item.id === userId.value); const machine = machines.value.find((item) => item.id === machineId.value); if (!resident || !machine) throw new Error('Choose a resident and machine.'); if (new Date(end.value).getTime() - new Date(start.value).getTime() !== 45 * 60 * 1000) throw new Error('Reservations must be exactly 45 minutes.'); reservations.value.push(await api.reservations.create({ userId: resident.id, userName: resident.name, machineId: machine.id, machineName: machine.name, machineType: machine.type, start: start.value, end: end.value })); showCreate.value = false } catch (error) { errorMessage.value = error instanceof Error ? error.message : 'Unable to create reservation.' } }
</script>
<template><div class="page-stack"><div class="section-heading"><div><span class="eyebrow">Operations</span><h2>Manage reservations</h2></div><button class="button button--accent" @click="showCreate = !showCreate">＋ Create reservation</button></div><form v-if="showCreate" class="filter-bar" @submit.prevent="createReservation"><select v-model="userId" required><option disabled value="">Resident</option><option v-for="resident in residents" :key="resident.id" :value="resident.id">{{ resident.name }}</option></select><select v-model="machineId" required><option disabled value="">Machine</option><option v-for="machine in machines.filter((item) => item.status !== 'maintenance')" :key="machine.id" :value="machine.id">{{ machine.name }}</option></select><input v-model="start" type="datetime-local" required /><input v-model="end" type="datetime-local" required /><button class="button button--dark">Save</button></form><p v-if="errorMessage" class="form-error">{{ errorMessage }}</p><div class="filter-bar"><input v-model="search" placeholder="Search resident or machine" /><select v-model="status"><option value="all">All statuses</option><option value="confirmed">Confirmed</option><option value="cancelled">Cancelled</option></select><input v-model="date" type="date" /><button class="button button--ghost" @click="search = ''; status = 'all'; date = ''">Clear</button></div><div class="schedule-list"><div v-for="reservation in filtered" :key="reservation.id" class="schedule-row"><div class="schedule-time"><strong>{{ new Date(reservation.start).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }) }}</strong><span>{{ new Date(reservation.end).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }) }}</span></div><div class="schedule-machine"><span class="machine-icon">{{ reservation.machineType === 'washer' ? 'W' : 'D' }}</span><span><strong>{{ reservation.machineName }}</strong><small>{{ reservation.userName }} · {{ new Date(reservation.start).toLocaleDateString() }}</small></span></div><span class="badge badge--success">{{ reservation.status }}</span><button v-if="reservation.status !== 'cancelled'" class="button button--ghost" @click="cancel(reservation)">Cancel</button></div><p v-if="!filtered.length" class="muted">No reservations match these filters.</p></div></div></template>
